const toggle=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');
function closeMenu(){nav.classList.remove('open');toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-label','メニューを開く')}
toggle.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';nav.classList.toggle('open',open);toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'メニューを閉じる':'メニューを開く')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav.classList.contains('open')){closeMenu();toggle.focus()}});
nav.addEventListener('keydown',e=>{if(e.key==='Tab'&&innerWidth<=900){const links=[...nav.querySelectorAll('a')];if(e.shiftKey&&document.activeElement===links[0]){e.preventDefault();toggle.focus()}}});
window.addEventListener('resize',()=>{if(innerWidth>900)closeMenu()});
const form=document.querySelector('#demo-form');
if(form){const fields=document.querySelector('#fields'),confirmation=document.querySelector('#confirmation'),error=document.querySelector('#errors'),review=document.querySelector('#review'),progress=[...document.querySelectorAll('.form-progress li')];
function state(n){progress.forEach((x,i)=>{x.classList.toggle('active',i===n);if(i===n)x.setAttribute('aria-current','step');else x.removeAttribute('aria-current')})}
form.addEventListener('submit',e=>{e.preventDefault();error.replaceChildren();document.querySelectorAll('.field-error').forEach(x=>x.remove());form.querySelectorAll('[aria-invalid]').forEach(x=>{x.removeAttribute('aria-invalid');x.removeAttribute('aria-describedby')});const issues=[];for(const [id,msg] of [['kind','ご希望の内容を選択してください。'],['name','デモ用のお名前を入力してください。'],['email','正しい形式のデモ用メールアドレスを入力してください。'],['consent','デモであることへの同意が必要です。']]){const el=document.getElementById(id);if(!el.checkValidity()||id==='name'&&!el.value.trim()){issues.push([el,msg]);el.setAttribute('aria-invalid','true');el.setAttribute('aria-describedby',id+'-error');const p=document.createElement('p');p.id=id+'-error';p.className='field-error';p.textContent=msg;el.closest('label.consent')?.after(p);if(!p.isConnected)el.after(p)}}if(issues.length){const p=document.createElement('p');p.textContent='入力内容を確認してください。';error.append(p);for(const [el,msg] of issues){const a=document.createElement('a');a.href='#'+el.id;a.textContent=msg;a.addEventListener('click',()=>el.focus());error.append(a,document.createElement('br'))}error.focus();return}review.replaceChildren();for(const [id,label] of [['kind','ご希望の内容'],['name','デモ用のお名前'],['email','デモ用メールアドレス'],['message','ご相談内容']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=document.getElementById(id).value||'入力なし';dd.style.whiteSpace='pre-wrap';dd.style.overflowWrap='anywhere';review.append(dt,dd)}fields.hidden=true;confirmation.hidden=false;state(1);confirmation.querySelector('h3').focus()});
document.querySelector('#back').addEventListener('click',()=>{confirmation.hidden=true;fields.hidden=false;state(0);document.querySelector('#kind').focus()});document.querySelector('#finish').addEventListener('click',()=>{form.reset();review.replaceChildren();confirmation.hidden=true;document.querySelector('#complete').hidden=false;state(2);document.querySelector('#complete').focus()});window.addEventListener('pagehide',()=>{form.reset();review.replaceChildren()})}
